    32→/// Signed transaction.
    33→#[cfg_attr(any(test, feature = "reth-codec"), reth_codecs::add_arbitrary_tests(rlp))]
    34→#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
    35→#[derive(Debug, Clone, Eq)]
    36→pub struct OpTransactionSigned {
    37→    /// Transaction hash
