    39→    hash: OnceLock<TxHash>,
    40→    /// The transaction signature values
    41→    signature: Signature,
    42→    /// Raw transaction info
    43→    transaction: OpTypedTransaction,
    44→}
    45→
    46→impl Deref for OpTransactionSigned {
    47→    type Target = OpTypedTransaction;
    48→    fn deref(&self) -> &Self::Target {
    49→        &self.transaction
    50→    }
    51→}
    52→
    53→impl OpTransactionSigned {
    54→    /// Creates a new signed transaction from the given transaction, signature and hash.
    55→    pub fn new(transaction: OpTypedTransaction, signature: Signature, hash: B256) -> Self {
    56→        Self { hash: hash.into(), signature, transaction }
    57→    }
    58→
    59→    #[cfg(test)]
    60→    fn input_mut(&mut self) -> &mut Bytes {
    61→        match &mut self.transaction {
