    63→            OpTypedTransaction::Eip2930(tx) => &mut tx.input,
    64→            OpTypedTransaction::Eip1559(tx) => &mut tx.input,
    65→            OpTypedTransaction::Eip7702(tx) => &mut tx.input,
    66→            OpTypedTransaction::Deposit(tx) => &mut tx.input,
    67→        }
    68→    }
