    71→    #[inline]
    72→    pub fn into_transaction(self) -> OpTypedTransaction {
    73→        self.transaction
    74→    }
    75→
    76→    /// Returns the transaction.
    77→    #[inline]
    78→    pub const fn transaction(&self) -> &OpTypedTransaction {
    79→        &self.transaction
    80→    }
    81→
    82→    /// Splits the `OpTransactionSigned` into its transaction and signature.
    83→    pub fn split(self) -> (OpTypedTransaction, Signature) {
    84→        (self.transaction, self.signature)
    85→    }
    86→
    87→    /// Creates a new signed transaction from the given transaction and signature without the hash.
    88→    ///
