    90→    pub fn new_unhashed(transaction: OpTypedTransaction, signature: Signature) -> Self {
    91→        Self { hash: Default::default(), signature, transaction }
    92→    }
    93→
    94→    /// Returns whether this transaction is a deposit.
    95→    pub const fn is_deposit(&self) -> bool {
    96→        matches!(self.transaction, OpTypedTransaction::Deposit(_))
    97→    }
