    99→    /// Splits the transaction into parts.
   100→    pub fn into_parts(self) -> (OpTypedTransaction, Signature, B256) {
   101→        let hash = *self.hash.get_or_init(|| self.recalculate_hash());
   102→        (self.transaction, self.signature, hash)
   103→    }
   104→}
