   106→impl SignerRecoverable for OpTransactionSigned {
   107→    fn recover_signer(&self) -> Result<Address, RecoveryError> {
   108→        // Optimism's Deposit transaction does not have a signature. Directly return the
   109→        // `from` address.
   110→        if let OpTypedTransaction::Deposit(TxDeposit { from, .. }) = self.transaction {
   111→            return Ok(from)
   112→        }
   113→
   114→        let Self { transaction, signature, .. } = self;
   115→        let signature_hash = signature_hash(transaction);
   116→        recover_signer(signature, signature_hash)
   117→    }
