   121→        // `from` address.
   122→        if let OpTypedTransaction::Deposit(TxDeposit { from, .. }) = &self.transaction {
   123→            return Ok(*from)
   124→        }
   125→
   126→        let Self { transaction, signature, .. } = self;
   127→        let signature_hash = signature_hash(transaction);
   128→        recover_signer_unchecked(signature, signature_hash)
   129→    }
