   134→            // `from` address.
   135→            OpTypedTransaction::Deposit(tx) => return Ok(tx.from),
   136→            OpTypedTransaction::Legacy(tx) => tx.encode_for_signing(buf),
   137→            OpTypedTransaction::Eip2930(tx) => tx.encode_for_signing(buf),
   138→            OpTypedTransaction::Eip1559(tx) => tx.encode_for_signing(buf),
   139→            OpTypedTransaction::Eip7702(tx) => tx.encode_for_signing(buf),
   140→        };
   141→        recover_signer_unchecked(&self.signature, keccak256(buf))
   142→    }
   143→}
