   233→            None
   234→        } else {
   235→            Some(self.ty())
   236→        }
   237→    }
   238→
   239→    fn encode_2718_len(&self) -> usize {
   240→        match &self.transaction {
   241→            OpTypedTransaction::Legacy(legacy_tx) => {
   242→                legacy_tx.eip2718_encoded_length(&self.signature)
   243→            }
   244→            OpTypedTransaction::Eip2930(access_list_tx) => {
   245→                access_list_tx.eip2718_encoded_length(&self.signature)
   246→            }
   247→            OpTypedTransaction::Eip1559(dynamic_fee_tx) => {
   248→                dynamic_fee_tx.eip2718_encoded_length(&self.signature)
   249→            }
   250→            OpTypedTransaction::Eip7702(set_code_tx) => {
   251→                set_code_tx.eip2718_encoded_length(&self.signature)
   252→            }
   253→            OpTypedTransaction::Deposit(deposit_tx) => deposit_tx.eip2718_encoded_length(),
   254→        }
   255→    }
   256→
   257→    fn encode_2718(&self, out: &mut dyn alloy_rlp::BufMut) {
   258→        let Self { transaction, signature, .. } = self;
   259→
   260→        match &transaction {
   261→            OpTypedTransaction::Legacy(legacy_tx) => {
   262→                // do nothing w/ with_header
   263→                legacy_tx.eip2718_encode(signature, out)
   264→            }
   265→            OpTypedTransaction::Eip2930(access_list_tx) => {
   266→                access_list_tx.eip2718_encode(signature, out)
   267→            }
   268→            OpTypedTransaction::Eip1559(dynamic_fee_tx) => {
   269→                dynamic_fee_tx.eip2718_encode(signature, out)
   270→            }
   271→            OpTypedTransaction::Eip7702(set_code_tx) => set_code_tx.eip2718_encode(signature, out),
   272→            OpTypedTransaction::Deposit(deposit_tx) => deposit_tx.encode_2718(out),
   273→        }
   274→    }
   275→}
