   277→impl Decodable2718 for OpTransactionSigned {
   278→    fn typed_decode(ty: u8, buf: &mut &[u8]) -> Eip2718Result<Self> {
   279→        match ty.try_into().map_err(|_| Eip2718Error::UnexpectedType(ty))? {
   280→            op_alloy_consensus::OpTxType::Legacy => Err(Eip2718Error::UnexpectedType(0)),
   281→            op_alloy_consensus::OpTxType::Eip2930 => {
   282→                let (tx, signature, hash) = TxEip2930::rlp_decode_signed(buf)?.into_parts();
   283→                let signed_tx = Self::new_unhashed(OpTypedTransaction::Eip2930(tx), signature);
   284→                signed_tx.hash.get_or_init(|| hash);
   285→                Ok(signed_tx)
   286→            }
   287→            op_alloy_consensus::OpTxType::Eip1559 => {
   288→                let (tx, signature, hash) = TxEip1559::rlp_decode_signed(buf)?.into_parts();
   289→                let signed_tx = Self::new_unhashed(OpTypedTransaction::Eip1559(tx), signature);
   290→                signed_tx.hash.get_or_init(|| hash);
   291→                Ok(signed_tx)
   292→            }
   293→            op_alloy_consensus::OpTxType::Eip7702 => {
   294→                let (tx, signature, hash) = TxEip7702::rlp_decode_signed(buf)?.into_parts();
   295→                let signed_tx = Self::new_unhashed(OpTypedTransaction::Eip7702(tx), signature);
   296→                signed_tx.hash.get_or_init(|| hash);
   297→                Ok(signed_tx)
   298→            }
   299→            op_alloy_consensus::OpTxType::Deposit => Ok(Self::new_unhashed(
   300→                OpTypedTransaction::Deposit(TxDeposit::rlp_decode(buf)?),
   301→                TxDeposit::signature(),
   302→            )),
   303→        }
   304→    }
   305→
   306→    fn fallback_decode(buf: &mut &[u8]) -> Eip2718Result<Self> {
   307→        let (transaction, signature) = TxLegacy::rlp_decode_with_signature(buf)?;
   308→        let signed_tx = Self::new_unhashed(OpTypedTransaction::Legacy(transaction), signature);
   309→
   310→        Ok(signed_tx)
   311→    }
   312→}
