   409→#[cfg(feature = "reth-codec")]
   410→impl reth_codecs::Compact for OpTransactionSigned {
   411→    fn to_compact<B>(&self, buf: &mut B) -> usize
   412→    where
   413→        B: bytes::BufMut + AsMut<[u8]>,
   414→    {
   415→        let start = buf.as_mut().len();
   416→
   417→        // Placeholder for bitflags.
   418→        // The first byte uses 4 bits as flags: IsCompressed[1bit], TxType[2bits], Signature[1bit]
   419→        buf.put_u8(0);
   420→
   421→        let sig_bit = self.signature.to_compact(buf) as u8;
   422→        let zstd_bit = self.transaction.input().len() >= 32;
   423→
   424→        let tx_bits = if zstd_bit {
   425→            let mut tmp = Vec::with_capacity(256);
   426→            if cfg!(feature = "std") {
   427→                reth_zstd_compressors::TRANSACTION_COMPRESSOR.with(|compressor| {
   428→                    let mut compressor = compressor.borrow_mut();
   429→                    let tx_bits = self.transaction.to_compact(&mut tmp);
   430→                    buf.put_slice(&compressor.compress(&tmp).expect("Failed to compress"));
   431→                    tx_bits as u8
   432→                })
   433→            } else {
   434→                let mut compressor = reth_zstd_compressors::create_tx_compressor();
   435→                let tx_bits = self.transaction.to_compact(&mut tmp);
   436→                buf.put_slice(&compressor.compress(&tmp).expect("Failed to compress"));
   437→                tx_bits as u8
   438→            }
   439→        } else {
   440→            self.transaction.to_compact(buf) as u8
   441→        };
   442→
   443→        // Replace bitflags with the actual values
   444→        buf.as_mut()[start] = sig_bit | (tx_bits << 1) | ((zstd_bit as u8) << 3);
   445→
   446→        buf.as_mut().len() - start
   447→    }
   448→
   449→    fn from_compact(mut buf: &[u8], _len: usize) -> (Self, &[u8]) {
   450→        use bytes::Buf;
   451→
   452→        // The first byte uses 4 bits as flags: IsCompressed[1], TxType[2], Signature[1]
   453→        let bitflags = buf.get_u8() as usize;
   454→
   455→        let sig_bit = bitflags & 1;
   456→        let (signature, buf) = Signature::from_compact(buf, sig_bit);
   457→
   458→        let zstd_bit = bitflags >> 3;
   459→        let (transaction, buf) = if zstd_bit != 0 {
   460→            if cfg!(feature = "std") {
   461→                reth_zstd_compressors::TRANSACTION_DECOMPRESSOR.with(|decompressor| {
   462→                    let mut decompressor = decompressor.borrow_mut();
   463→
   464→                    // TODO: enforce that zstd is only present at a "top" level type
   465→                    let transaction_type = (bitflags & 0b110) >> 1;
   466→                    let (transaction, _) = OpTypedTransaction::from_compact(
   467→                        decompressor.decompress(buf),
   468→                        transaction_type,
   469→                    );
   470→
   471→                    (transaction, buf)
   472→                })
   473→            } else {
   474→                let mut decompressor = reth_zstd_compressors::create_tx_decompressor();
   475→                let transaction_type = (bitflags & 0b110) >> 1;
   476→                let (transaction, _) = OpTypedTransaction::from_compact(
   477→                    decompressor.decompress(buf),
   478→                    transaction_type,
   479→                );
   480→
   481→                (transaction, buf)
   482→            }
   483→        } else {
   484→            let transaction_type = bitflags >> 1;
   485→            OpTypedTransaction::from_compact(buf, transaction_type)
   486→        };
   487→
   488→        (Self { signature, transaction, hash: Default::default() }, buf)
   489→    }
   490→}
