   493→impl<'a> arbitrary::Arbitrary<'a> for OpTransactionSigned {
   494→    fn arbitrary(u: &mut arbitrary::Unstructured<'a>) -> arbitrary::Result<Self> {
   495→        let mut transaction = OpTypedTransaction::arbitrary(u)?;
   496→
   497→        let secp = secp256k1::Secp256k1::new();
   498→        let key_pair = secp256k1::Keypair::new(&secp, &mut rand_08::thread_rng());
   499→        let signature = reth_primitives_traits::crypto::secp256k1::sign_message(
   500→            B256::from_slice(&key_pair.secret_bytes()[..]),
   501→            signature_hash(&transaction),
   502→        )
   503→        .unwrap();
   504→
   505→        let signature = if transaction.is_deposit() { TxDeposit::signature() } else { signature };
   506→
   507→        Ok(Self::new_unhashed(transaction, signature))
   508→    }
   509→}
