   511→/// Calculates the signing hash for the transaction.
   512→fn signature_hash(tx: &OpTypedTransaction) -> B256 {
   513→    match tx {
   514→        OpTypedTransaction::Legacy(tx) => tx.signature_hash(),
   515→        OpTypedTransaction::Eip2930(tx) => tx.signature_hash(),
   516→        OpTypedTransaction::Eip1559(tx) => tx.signature_hash(),
   517→        OpTypedTransaction::Eip7702(tx) => tx.signature_hash(),
   518→        OpTypedTransaction::Deposit(_) => B256::ZERO,
   519→    }
   520→}
